"""Helpers for Dasel recursive descent and search selectors.

These operate on ordinary Python JSON-like values and are kept separate from
the query parser so the CLI implementation can use them directly.
"""

def _children(value):
    if isinstance(value, dict):
        return value.values()
    if isinstance(value, list):
        return value
    return ()


def recursive_values(root, key):
    """Return values at key in descendant objects, in depth-first order.

    The root object's own keys are not considered by the reference `..key`
    selector; its children are searched.
    """
    out = []
    def walk(value):
        if isinstance(value, dict):
            for k, v in value.items():
                if k == key:
                    out.append(v)
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    for child in _children(root):
        walk(child)
    return out


def search_objects(root, key, operator, expected):
    """Find descendant objects whose direct property satisfies a comparison."""
    def matches(value):
        if key not in value:
            return False
        actual = value[key]
        try:
            return {
                '==': lambda: actual == expected,
                '!=': lambda: actual != expected,
                '>': lambda: actual > expected,
                '<': lambda: actual < expected,
                '>=': lambda: actual >= expected,
                '<=': lambda: actual <= expected,
            }[operator]()
        except (KeyError, TypeError):
            return False

    out = []
    def walk(value):
        if isinstance(value, dict):
            if matches(value):
                out.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)
    # As with recursive descent, the top level itself isn't a candidate.
    for child in _children(root):
        walk(child)
    return out
"""Small helpers for Dasel's auxiliary CLI commands."""

import sys


def run_auxiliary(argv):
    """Handle commands that don't need to parse a data document.

    Return True when argv was handled, otherwise False.
    """
    if not argv or argv[0] not in ("version", "completion", "man"):
        return False
    command = argv[0]
    args = argv[1:]
    if args and args[0] in ("-h", "--help"):
        if command == "completion":
            print('Usage: dasel completion <shell>\n\nGenerate shell completion script\n\nArguments:\n  <shell>    Shell type (bash, zsh, fish, powershell)\n\nFlags:\n  -h, --help    Show context-sensitive help.')
        elif command == "man":
            print('Usage: dasel man\n\nGenerate man page\n\nFlags:\n  -h, --help    Show context-sensitive help.')
        else:
            print('Usage: dasel version\n\nPrint the version\n\nFlags:\n  -h, --help    Show context-sensitive help.')
        return True
    if command == "version":
        print("3.11.0")
        return True
    # Completion and man documents are generated from the CLI schema. Leave
    # them to the primary CLI implementation when it has a generator.
    return False

import sys,json,re,argparse

def parse_selector(s):
    # Split property paths, preserving quoted bracket keys and numeric indexes.
    parts=[]; i=0; buf=''
    while i<len(s):
        c=s[i]
        if c=='.':
            if buf: parts.append(('key',buf));buf=''
            i+=1
            if i<len(s) and s[i]=='.': parts.append(('recursive',None));i+=1
        elif c=='[':
            if buf: parts.append(('key',buf));buf=''
            j=s.find(']',i+1)
            if j<0: raise ValueError('invalid index')
            x=s[i+1:j].strip()
            if x.startswith(('"',"'")):
                try: x=json.loads(x.replace("'",'"'))
                except: x=x[1:-1]
                parts.append(('key',x))
            else: parts.append(('index',int(x)))
            i=j+1
        else: buf+=c;i+=1
    if buf: parts.append(('key',buf))
    return parts

def walk_recursive(v,key):
    found=[]
    if isinstance(v,dict):
        if key in v: found.append(v[key])
        for x in v.values(): found.extend(walk_recursive(x,key))
    elif isinstance(v,list):
        for x in v: found.extend(walk_recursive(x,key))
    return found

def select(root,parts):
    vals=[root]
    for typ,arg in parts:
        out=[]
        for v in vals:
            if typ=='recursive':
                # recursive marker is followed by key selector
                continue
            try:
                if typ=='key': out.append(v[arg])
                elif typ=='index': out.append(v[arg])
            except (KeyError,IndexError,TypeError): raise ValueError(f'map key not found: "{arg}"' if typ=='key' else 'index out of range')
        if typ=='recursive':
            continue
        vals=out
    return vals[0] if len(vals)==1 else vals

def format_out(v,compact=False):
    if isinstance(v,str): return json.dumps(v,ensure_ascii=False)
    return json.dumps(v,ensure_ascii=False,separators=(',',':') if compact else None,indent=None if compact else 4)

def main():
    args=sys.argv[1:]
    if args and args[0] in ('version','--version','-v'):
        print('3.11.0');return
    if args and args[0] in ('--help','-h'):
        print('Usage: dasel <command>\n\nQuery and modify data structures from the command line.\n\nCommands: query, version, interactive, completion, man');return
    if args and args[0]=='query': args=args[1:]
    if '--help' in args or '-h' in args:
        print('Usage: dasel query [<query>] [flags]\nFlags: -i, --in; -o, --out; --root; --compact');return
    inp='json'; outfmt=None; compact=False; rootflag=False; query=None; i=0
    while i<len(args):
        a=args[i]
        if a in ('-i','--in'): i+=1; inp=args[i]
        elif a.startswith('--in='):inp=a.split('=',1)[1]
        elif a in ('-o','--out'):i+=1;outfmt=args[i]
        elif a.startswith('--out='):outfmt=a.split('=',1)[1]
        elif a=='--compact':compact=True
        elif a=='--root':rootflag=True
        elif a.startswith('-'): pass
        elif query is None:query=a
        i+=1
    raw=sys.stdin.read()
    try:
        if inp not in ('json',''): raise ValueError('unsupported input format')
        data=json.loads(raw)
        if query:
            fm=re.fullmatch(r'(keys|values|count|toString)\((.*)\)',query.strip())
            if fm:
                fn,arg=fm.groups(); arg=arg.strip()
                if fn in ('keys','values'):
                    v=data if not arg else select(data,parse_selector(arg))
                    if not isinstance(v,dict): raise ValueError('expected map')
                    result=list(v) if fn=='keys' else list(v.values())
                elif fn=='count':
                    v=data if not arg else select(data,parse_selector(arg))
                    if not isinstance(v,(list,dict,str)): raise ValueError('expected array, map, or string')
                    result=len(v)
                else:
                    v=data if not arg else select(data,parse_selector(arg))
                    result=str(v)
            else:
                m=re.match(r'^(.*?)\s*=\s*(.+)$',query)
