def parse_selector(s):
    # Split property paths, preserving quoted bracket keys and numeric indexes.
    parts=[]; i=0; buf=''
    while i<len(s):
        c=s[i]
        if c=='.':
            if buf: parts.append(('key',buf));buf=''
            i+=1
            if i<len(s) and s[i]=='.': parts.append(('recursive',None));i+=1
        elif c=='[':
            if buf: parts.append(('key',buf));buf=''
            j=s.find(']',i+1)
            if j<0: raise ValueError('invalid index')
            x=s[i+1:j].strip()
            if x.startswith(('"',"'")):
                try: x=json.loads(x.replace("'",'"'))
                except: x=x[1:-1]
                parts.append(('key',x))
            else: parts.append(('index',int(x)))
            i=j+1
        else: buf+=c;i+=1
    if buf: parts.append(('key',buf))
    return parts

def walk_recursive(v,key):
    return recursive_values(v,key)

def select(root,parts):
    vals=[root]
    for typ,arg in parts:
        out=[]
        for v in vals:
            if typ=='recursive':
                # recursive marker is followed by key selector
                continue
            try:
                if typ=='key': out.append(v[arg])
                elif typ=='index': out.append(v[arg])
            except (KeyError,IndexError,TypeError): raise ValueError(f'map key not found: "{arg}"' if typ=='key' else f'slice index out of range: {arg}')
        if typ=='recursive':
            continue
        vals=out
    return vals[0] if len(vals)==1 else vals

def eval_expr(expr, item):
    expr=expr.strip()
    if expr.startswith("$this"):
        expr="item"+expr[5:]
    elif re.fullmatch(r"[A-Za-z_][\w-]*",expr):
        if isinstance(item,dict):
            if expr not in item: raise ValueError(f'map key not found: "{expr}"')
            return item[expr]
        raise ValueError("unexpected type: expected map, got "+type(item).__name__)
    if isinstance(item,dict):
        expr=re.sub(r"(?<![\w\"'])\b([A-Za-z_][\w]*)\b(?![\w\"'])(?!\s*\()", lambda m: m.group(0) if m.group(1) in ("True","False","None","and","or","not","in") else "item["+repr(m.group(1))+"]", expr)
    expr=re.sub(r"\btrue\b", "True", expr, flags=re.I)
    expr=re.sub(r"\bfalse\b", "False", expr, flags=re.I)
    expr=re.sub(r"\bnull\b", "None", expr, flags=re.I)
    try:
        return eval(expr, {"__builtins__":{}}, {"item":item})
    except Exception as e:
        raise ValueError(str(e))

def collection_query(data, query):
    m=re.fullmatch(r"(.+?)\.(filter|map|each|any|all|count)\((.*)\)",query)
    if not m: return None,False
    path,op,expr=m.groups(); seq=select(data,parse_selector(path))
    if not isinstance(seq,list): raise ValueError(f"unexpected type: expected array, got {type(seq).__name__}")
    if op=="filter": return [x for x in seq if eval_expr(expr,x)],True
    if op=="map": return [eval_expr(expr,x) for x in seq],True
    if op=="each":
        if "=" in expr:
            lhs,rhs=expr.split("=",1)
            return [eval_expr(rhs,x) for x in seq],True
        return seq,True
    results=[bool(eval_expr(expr,x)) for x in seq]
    if op=="any": return any(results),True
    if op=="all": return all(results),True
    return sum(results),True

def format_out(v,compact=False):
    return json_dumps(v,compact)

