                if isinstance(k,str) and k.startswith('-'): attrs.append((k[1:],v))
            attrtext=''.join(f' {k}="{_xml_escape(_cell(v),True)}"' for k,v in attrs)
            children=[(k,v) for k,v in val.items() if not (isinstance(k,str) and k.startswith('-')) and k!='#text']
            txt=val.get('#text','')
            if not children and not txt: return f'{indent}<{name}{attrtext}/>'
            if not children: return f'{indent}<{name}{attrtext}>{_xml_escape(_cell(txt))}</{name}>'
            body=[]
            if txt: body.append(' '* (depth+2)+_xml_escape(_cell(txt)))
            for k,v in children: body.append(emit(k,v,depth+2))
            return f'{indent}<{name}{attrtext}>\n'+'\n'.join(body)+f'\n{indent}</{name}>'
