            raise FunctionError(f'error getting slice length: unexpected type: expected array, got {type_name(value)}')
        return False
    if name in ("toString", "toInt", "toFloat", "toBool"):
        if name == "toString":
            if isinstance(value, (dict, list)):
                raise FunctionError(f'cannot convert {type_name(value)} to string')
            return "" if value is None else str(value).lower() if isinstance(value, bool) else str(value)
        if name == "toInt":
            return int(value)
        if name == "toFloat":
            return float(value)
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() == "true"
        return bool(value)
    raise FunctionError(f'unknown function: "{name}"')


def type_name(value):
    if value is None:
        return "nil"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, dict):
        return "map"
    if isinstance(value, list):
        return "array"
    if isinstance(value, str):
        return "string"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "float"
    return type(value).__name__
    return [{k: (row[i] if i<len(row) else '') for i,k in enumerate(headers)} for row in rows[1:]]

def parse_xml(text):
    root=ET.fromstring(text)
    def node(el):
        obj={'-'+k:v for k,v in el.attrib.items()}
        children=list(el)
        if not children:
            txt=(el.text or '')
            if obj:
                if txt: obj['#text']=txt
                return obj
            return txt
        mixed=(el.text or '')+''.join(child.tail or '' for child in children)
        if mixed: obj['#text']=mixed
        for child in children:
            val=node(child)
            if child.tag in obj:
                if not isinstance(obj[child.tag],list): obj[child.tag]=[obj[child.tag]]
                obj[child.tag].append(val)
            else: obj[child.tag]=val
        return obj
    return {root.tag:node(root)}

def parse_xml_structured(text):
    root=ET.fromstring(text)
    def elem(el):
        return {'name':el.tag,'attrs':dict(el.attrib),'content':el.text or '', 'children':[elem(c) for c in list(el)]}
    return {'name':'root','attrs':{},'content':'','children':[elem(root)]}

def dump_xml_structured(value):
    from xml.sax.saxutils import escape
    def scalar(v):
        if v is None: return ""
        if isinstance(v, bool): return "true" if v else "false"
        return escape(str(v))
    def field(key, val, depth):
        pad=" "*depth
        if isinstance(val, dict):
            if not val: return [f"{pad}<{key}></{key}>"]
            lines=[f"{pad}<{key}>"]
            for k,v in val.items(): lines.extend(field(k,v,depth+2))
            lines.append(f"{pad}</{key}>")
            return lines
        if isinstance(val, list):
            if not val: return []
            if depth == 0:
                lines=[f"{pad}<{key}>"]
                for item in val:
                    if isinstance(item,dict):
                        for k,v in item.items(): lines.extend(field(k,v,depth+2))
                    else: lines.extend(field(key,item,depth+2))
                lines.append(f"{pad}</{key}>")
                return lines
            lines=[]
            for item in val:
                if isinstance(item,dict):
                    lines.append(f"{pad}<{key}>")
                    for k,v in item.items(): lines.extend(field(k,v,depth+2))
                    lines.append(f"{pad}</{key}>")
                else: lines.extend(field(key,item,depth))
            return lines
        return [f"{pad}<{key}>{scalar(val)}</{key}>"]
    if isinstance(value,dict):
        blocks=[]
        for k,v in value.items(): blocks.append("\n".join(field(k,v,0)))
        return "\n\n".join(blocks)+"\n"
    return scalar(value)+"\n"

def write_csv(value):
    if not isinstance(value,list): value=[value]
    if not value: return ''
    if not all(isinstance(x,dict) for x in value): return '\n'.join(str(x) for x in value)
    fields=list(dict.fromkeys(k for row in value for k in row))
    stream=io.StringIO(newline=''); w=csv.DictWriter(stream,fieldnames=fields,lineterminator='\n'); w.writeheader();w.writerows(value)
    return stream.getvalue()

def write_xml(value):
    def add(parent,key,val):
        if str(key).startswith('-'):
            parent.set(str(key)[1:],str(val)); return None
        if key=='#text':
            parent.text='' if val is None else str(val); return None
        el=ET.SubElement(parent,str(key))
        if isinstance(val,dict):
            for k,v in val.items(): add(el,k,v)
        elif isinstance(val,list):
            el.clear()
            for x in val: add(el,'item',x)
        elif val is not None: el.text=str(val)
        return el
    if isinstance(value,dict) and len(value)==1:
        key,val=next(iter(value.items())); root=ET.Element(str(key))
        if isinstance(val,dict):
            for k,v in val.items(): add(root,k,v)
        elif val is not None: root.text=str(val)
    else:
        root=ET.Element('root')
        if isinstance(value,dict):
            for k,v in value.items(): add(root,k,v)
        elif isinstance(value,list):
            for v in value: add(root,'item',v)
        elif value is not None: root.text=str(value)
    return ET.tostring(root,encoding='unicode')+'\n'

