class RangeSelectorError(Exception):
    pass

def parse_selector(s):
    # Split property paths, preserving quoted bracket keys and numeric indexes.
    parts=[]; i=0; buf=''
    while i<len(s):
        c=s[i]
        if c=='.':
            if buf: parts.append(('literal',int(buf)) if re.fullmatch(r'\d+',buf) else ('key',buf));buf=''
            i+=1
            if i<len(s) and s[i]=='.': parts.append(('recursive',None));i+=1
        elif c=='[':
            if buf: parts.append(('key',buf));buf=''
            j=s.find(']',i+1)
            if j<0: raise ValueError('invalid index')
            x=s[i+1:j].strip()
            if x.startswith(('"',"'")):
                try: x=json.loads(x.replace("'",'"'))
                except: x=x[1:-1]
                parts.append(('key',x))
            elif ':' in x:
                if x.count(':') != 1: raise ValueError('invalid range')
                start,end=x.split(':',1)
                if not start.strip() and not end.strip(): raise ValueError('invalid range')
                parts.append(('range',(int(start) if start.strip() else None,int(end) if end.strip() else None)))
            else: parts.append(('index',int(x)))
            i=j+1
        else: buf+=c;i+=1
    if buf: parts.append(('literal',int(buf)) if re.fullmatch(r'\d+',buf) else ('key',buf))
    return parts

def walk_recursive(v,key):
    return recursive_values(v,key)

def select(root,parts):
    vals=[root]
    for step,(typ,arg) in enumerate(parts):
        out=[]
        for v in vals:
            if typ=='recursive':
                # recursive marker is followed by key selector
                continue
            try:
                if typ=='literal':
                    out.append(arg)
                elif typ=='key':
                    if not isinstance(v,dict):
                        kind='null' if v is None else 'array' if isinstance(v,list) else 'int' if isinstance(v,int) and not isinstance(v,bool) else 'string' if isinstance(v,str) else 'bool' if isinstance(v,bool) else 'map'
                        raise ValueError(f'unexpected type: expected map, got {kind}')
                    if arg not in v: raise KeyError(arg)
                    out.append(v[arg])
                elif typ=='range':
                    if not isinstance(v,list):
                        kind='null' if v is None else 'array' if isinstance(v,list) else 'int' if isinstance(v,int) and not isinstance(v,bool) else 'string' if isinstance(v,str) else 'bool' if isinstance(v,bool) else 'map'
                        raise ValueError(f'unexpected type: expected array, got {kind}')
                    start,end=arg
                    start=0 if start is None else (start+len(v) if start < 0 else start)
                    end=len(v)-1 if end is None else (end+len(v) if end < 0 else end)
                    if start < 0 or start >= len(v): raise RangeSelectorError(str(start))
                    if end < 0: raise RangeSelectorError(str(end))
                    if end >= len(v): raise RangeSelectorError(str(len(v)))
                    step=1 if start <= end else -1
                    out.extend(v[i] for i in range(start,end+step,step))
                elif typ=='index':
                    if not isinstance(v,list):
                        kind='null' if v is None else 'array' if isinstance(v,list) else 'int' if isinstance(v,int) and not isinstance(v,bool) else 'string' if isinstance(v,str) else 'bool' if isinstance(v,bool) else 'map'
                        raise ValueError(f'unexpected type: expected array, got {kind}')
                    if isinstance(v,list) and (arg < 0 or arg >= len(v)):
                        raise IndexError
                    out.append(v[arg])
            except (KeyError,IndexError,TypeError):
                msg=f'map key not found: "{arg}"' if typ=='key' else f'slice index out of range: {arg}'
                if step or typ=='index': raise ValueError('chained selector error: '+msg)
                raise ValueError(msg)
            except ValueError as exc:
                if step: raise ValueError('chained selector error: '+str(exc))
                raise
        if typ=='recursive':
            continue
        vals=out
    return vals[0] if len(vals)==1 else vals

